import { Component, EventEmitter, Input, Output } from '@angular/core';

@Component({
  selector: 'app-modal',
  templateUrl: './modal.component.html',
  styleUrls: ['./modal.component.css']
})
export class ModalComponent {
  @Input() show: boolean = false;
  @Input() title: string = '';
  @Input() showFooter: boolean = true;
  @Input() confirmLabel: string = 'Confirmar';
  @Input() cancelLabel: string = 'Cancelar';
  @Input() confirmVariant: 'primary' | 'danger' | 'success' = 'primary';
  @Output() confirmed = new EventEmitter<void>();
  @Output() closed = new EventEmitter<void>();

  onConfirm(): void {
    this.confirmed.emit();
  }

  onClose(): void {
    this.closed.emit();
  }

  onBackdropClick(event: MouseEvent): void {
    if (event.target === event.currentTarget) {
      this.onClose();
    }
  }
}
<div *ngIf="show" class="modal-backdrop" (click)="onBackdropClick($event)">
  <div class="modal-container">
    <div class="modal-header">
      <h3>{{ title }}</h3>
      <button class="close-btn" (click)="onClose()" aria-label="Cerrar">×</button>
    </div>

    <div class="modal-body">
      <ng-content></ng-content>
    </div>

    <div *ngIf="showFooter" class="modal-footer">
      <app-button
        [label]="cancelLabel"
        variant="secondary"
        (clicked)="onClose()">
      </app-button>
      <app-button
        [label]="confirmLabel"
        [variant]="confirmVariant"
        (clicked)="onConfirm()">
      </app-button>
    </div>
  </div>
</div>
